SELECT jsonb_build_object('current_user', current_user, 'bypassrls', (SELECT rolbypassrls FROM pg_roles WHERE rolname = current_user), 'eligibility_rule_set_rows', (SELECT count(*) FROM app.rule_set WHERE decision_key = 'DK-application.eligibility'), 'eligibility_tenants', (SELECT count(DISTINCT tenant_id) FROM app.rule_set WHERE decision_key = 'DK-application.eligibility'), 'tenants', (SELECT count(*) FROM app.tenant), 'anon_usage_app', has_schema_privilege('anon', 'app', 'USAGE'), 'authenticated_usage_app', has_schema_privilege('authenticated', 'app', 'USAGE'), 'dsa_app_usage_app', has_schema_privilege('dsa_app', 'app', 'USAGE')) AS state;
